-- Krossi-kenttävaraus: ensimmäinen halli, Lahden Tennis- ja Squashkeskus — Janus-Areena,
-- Kispi-Areena ja Kisapuiston ulkokentät.
--
-- is_public = false: halli näkyy vain Krossin ylläpidolle (ja henkilökunnalle, kun sellainen
-- lisätään booking_staff-tauluun), kunnes halli on sopinut mukaan tulosta. Julkaisu myöhemmin:
--   update public.booking_venues set is_public = true where slug = 'lahden-tennis-ja-squash';
--
-- Hinnat ovat hallin nykyinen hintataso (luettu Cintoiasta, syksy 2026); tarkistetaan hallin
-- kanssa ennen julkaisua. Samat säännöt kuin sovelluksen demossa (src/api/demo/bookingSeed.js).
-- Sisätennisrivit on rajattu kahdeksaan sisäkenttään (court_ids): pelkällä lajilla ('tennis')
-- ne osuisivat myös ulkokenttiin, jolloin ulkokentät olisivat varattavissa myös klo 8–21:n
-- ulkopuolella sisähinnalla. Ulkokentät hinnoittelee vain niiden oma rivi.
--
-- Kiinteät uuid:t, jotta data on vakaa (linkit, testit, myöhemmät migraatiot):
--   b00c0000-0000-4000-a000-…  halli (…001) ja toimipaikat (…011 Janus, …012 Kispi, …013 Kisapuisto)
--   b00c0000-0000-4000-a001-…  Janus-Areenan kentät
--   b00c0000-0000-4000-a002-…  Kispi-Areenan kentät
--   b00c0000-0000-4000-a003-…  Kisapuiston ulkokentät
--   b00c0000-0000-4000-a009-…  hintasäännöt

-- Viime hetken ale on pois päältä (last_minute_hours null), kunnes halli päättää toisin.
insert into public.booking_venues (
  id, slug, name, city, timezone, open_from, open_until, slot_minutes, durations,
  days_ahead, cancel_limit_hours, hold_minutes, last_minute_hours, last_minute_percent, is_public
) values (
  'b00c0000-0000-4000-a000-000000000001', 'lahden-tennis-ja-squash', 'Lahden Tennis- ja Squashkeskus', 'Lahti',
  'Europe/Helsinki', '06:00', '23:00', 30, '{60,90,120}', 14, 24, 10, null, 0, false
)
on conflict (id) do nothing;

